class Body{constructor(mass,p=new V(),size=new V(4.3,.8,1.9)){this.mass=mass;this.p=p;this.v=new V();this.w=new V();this.q=new Q();this.size=size;this.force=new V();this.torque=new V();this.inertia=new V(mass*(size.y*size.y+size.z*size.z)/12,mass*(size.x*size.x+size.z*size.z)/12,mass*(size.x*size.x+size.y*size.y)/12);this.active=true} point(v){return this.q.rotate(v).add(this.p)} velocity(r){return this.v.clone().add(this.w.cross(r))} invI(v){let l=this.q.inv().rotate(v);l.x/=this.inertia.x;l.y/=this.inertia.y;l.z/=this.inertia.z;return this.q.rotate(l)} apply(f,local){this.force.add(f);if(local)this.torque.add(this.q.rotate(local).cross(f))} integrate(dt,g){this.v.add(this.force.mul(dt/this.mass));this.v.y-=g*dt;const localW=this.q.inv().rotate(this.w),iw=new V(localW.x*this.inertia.x,localW.y*this.inertia.y,localW.z*this.inertia.z),gyro=this.q.rotate(localW.cross(iw));this.w.add(this.invI(this.torque.clone().sub(gyro)).mul(dt));this.w.mul(Math.exp(-.12*dt));this.p.add(this.v.clone().mul(dt));this.q.step(this.w,dt);this.force=new V();this.torque=new V()} impulse(j,r){this.v.add(j.clone().mul(1/this.mass));this.w.add(this.invI(r.cross(j)))} serialize(){return [...this.p.arr(),...this.q.arr(),...this.v.arr(),...this.w.arr()]}}
